1	import { Editor, TLShapeId } from "tldraw";
2	import { MtgCardShape } from "../../shared/mtgCardShape";
3	import { ZoneHit } from "./zoneHitTest";
4	import { evictPassengers } from "./cardZoneEntry";
5	
6	const SWALLOW_DURATION_MS = 500;
7	const SWALLOW_SPINS = 2;
8	
9	interface SwallowSnapshot {
10	  x: number;
11	  y: number;
12	  rotation: number;
13	  opacity: number;
14	  props: MtgCardShape["props"];
15	}
16	
17	/**
18	 * The library portal's swallow (ticket 12): spins the card twice while shrinking and
19	 * fading it into the library's center over ~500ms, then — send-then-commit — deletes it
20	 * only once the Tabletop server confirms the Spine accepted `card.returned.v1`. On
21	 * failure the card's visuals revert and it stays on the table; nothing here deletes
22	 * synchronously, since tldraw non-null-asserts every still-settling shape in a
23	 * multi-select drag (see `owners/tabletop-shape-mechanics`).
24	 */
25	export function swallowCard(editor: Editor, current: MtgCardShape, zoneHit: ZoneHit): void {
26	  evictPassengers(editor, current, zoneHit);
27	
28	  const zoneBounds = editor.getShapePageBounds(zoneHit.id);
29	  if (!zoneBounds) return;
30	
31	  const before: SwallowSnapshot = {
32	    x: current.x,
33	    y: current.y,
34	    rotation: current.rotation,
35	    opacity: current.opacity,
36	    props: current.props,
37	  };
38	
39	  editor.animateShapes(
40	    [
41	      {
42	        id: current.id,
43	        type: current.type,
44	        x: zoneBounds.center.x - 0.5,
45	        y: zoneBounds.center.y - 0.5,
46	        rotation: current.rotation + SWALLOW_SPINS * 2 * Math.PI,
47	        opacity: 0,
48	        props: { ...current.props, w: 1, h: 1 },
49	      },
50	    ],
51	    { animation: { duration: SWALLOW_DURATION_MS } }
52	  );
53	
54	  const id = current.id;
55	  const { owner, scryfallId, gameCardIndex } = current.props;
56	
57	  setTimeout(() => {
58	    void completeSwallow(editor, id, before, { owner, scryfallId, gameCardIndex });
59	  }, 0);
60	}
61	
62	async function completeSwallow(
63	  editor: Editor,
64	  id: TLShapeId,
65	  before: SwallowSnapshot,
66	  send: { owner: string; scryfallId: string; gameCardIndex: number | null }
67	): Promise<void> {
68	  const [ok] = await Promise.all([postCardReturned(send), sleep(SWALLOW_DURATION_MS)]);
69	
70	  if (!editor.getShape(id)) return; // already gone (e.g. store reset mid-flight)
71	
72	  if (ok) {
73	    editor.deleteShapes([id]);
74	  } else {
75	    editor.animateShapes(
76	      [{ id, type: "mtg-card", x: before.x, y: before.y, rotation: before.rotation, opacity: before.opacity, props: before.props }],
77	      { animation: { duration: 200 } }
78	    );
79	  }
80	}
81	
82	function sleep(ms: number): Promise<void> {
83	  return new Promise((resolve) => setTimeout(resolve, ms));
84	}
85	
86	function tableSlugFromLocation(): string | undefined {
87	  const match = window.location.pathname.match(/^\/t\/([^/]+)$/);
88	  return match ? decodeURIComponent(match[1]) : undefined;
89	}
90	
91	async function postCardReturned(send: { owner: string; scryfallId: string; gameCardIndex: number | null }): Promise<boolean> {
92	  if (send.gameCardIndex === null) return false;
93	  const tableSlug = tableSlugFromLocation();
94	  if (!tableSlug) return false;
95	
96	  try {
97	    const response = await fetch(`/api/tables/${encodeURIComponent(tableSlug)}/cards/return`, {
98	      method: "POST",
99	      headers: { "content-type": "application/json" },
100	      body: JSON.stringify({ seatId: send.owner, scryfallId: send.scryfallId, gameCardIndex: send.gameCardIndex }),
101	    });
102	    return response.ok;
103	  } catch {
104	    return false;
105	  }
106	}
