1	import { Computed, computed, Editor, TLShapeId, useValue, VecLike } from "tldraw";
2	import { MtgZoneShapeProps } from "../../shared/mtgZoneShape";
3	import { MtgCardShape } from "../../shared/mtgCardShape";
4	
5	export interface ZoneHit {
6	  id: TLShapeId;
7	  zone: MtgZoneShapeProps["zone"];
8	  seatId: MtgZoneShapeProps["seatId"];
9	}
10	
11	export function topmostZoneAt(editor: Editor, center: VecLike): ZoneHit | undefined {
12	  let winner: (ZoneHit & { index: string }) | undefined;
13	  for (const candidate of editor.getCurrentPageShapes()) {
14	    if (candidate.type !== "mtg-zone") continue;
15	    const bounds = editor.getShapePageBounds(candidate);
16	    if (!bounds?.containsPoint(center)) continue;
17	    if (!winner || candidate.index > winner.index) {
18	      const props = candidate.props as MtgZoneShapeProps;
19	      winner = { id: candidate.id, zone: props.zone, seatId: props.seatId, index: candidate.index };
20	    }
21	  }
22	  return winner;
23	}
24	
25	const armedZoneIdByEditor = new WeakMap<Editor, Computed<TLShapeId | undefined>>();
26	function armedZoneIdSignal(editor: Editor) {
27	  let signal = armedZoneIdByEditor.get(editor);
28	  if (!signal) {
29	    signal = computed("armedZoneId", () => {
30	      if (!editor.isIn("select.translating")) return undefined;
31	      const hit = topmostZoneAt(editor, editor.inputs.currentPagePoint);
32	      if (!hit) return undefined;
33	      if (hit.zone === "command" && !allDraggedCardsAreOwnersCommander(editor, hit.seatId)) {
34	        return undefined;
35	      }
36	      if (hit.zone === "library" && !allDraggedCardsBelongToOwner(editor, hit.seatId)) {
37	        return undefined;
38	      }
39	      return hit.id;
40	    });
41	    armedZoneIdByEditor.set(editor, signal);
42	  }
43	  return signal;
44	}
45	
46	function allDraggedCardsAreOwnersCommander(editor: Editor, seatId: string | null): boolean {
47	  const draggedCards = editor
48	    .getSelectedShapes()
49	    .filter((shape): shape is MtgCardShape => shape.type === "mtg-card");
50	  if (draggedCards.length === 0) return false;
51	  return draggedCards.every((card) => card.props.owner === seatId && card.props.isCommander);
52	}
53	
54	/**
55	 * The library portal's gate (ticket 12): only the player's own library swallows a card,
56	 * and only cards — a dragged counter (or any non-card selection) must not arm it. A card
57	 * with no `gameCardIndex` can never be sent as `card.returned.v1`, so it's excluded too.
58	 * A mixed-ownership multi-select doesn't arm at all — one destination for the whole group,
59	 * or none, same posture as the command-zone gate above.
60	 */
61	export function allDraggedCardsBelongToOwner(editor: Editor, seatId: string | null): boolean {
62	  const selected = editor.getSelectedShapes();
63	  const draggedCards = selected.filter((shape): shape is MtgCardShape => shape.type === "mtg-card");
64	  if (draggedCards.length === 0 || draggedCards.length !== selected.length) return false;
65	  return draggedCards.every((card) => card.props.owner === seatId && card.props.gameCardIndex !== null);
66	}
67	
68	export function useIsZoneArmed(editor: Editor, zoneId: TLShapeId): boolean {
69	  return useValue("isZoneArmed", () => armedZoneIdSignal(editor).get() === zoneId, [editor, zoneId]);
70	}
71	
72	/** The armed zone's id, but only when it's a library — for the swirl overlay (ticket 12). */
73	export function useArmedLibraryZoneId(editor: Editor): TLShapeId | undefined {
74	  return useValue(
75	    "armedLibraryZoneId",
76	    () => {
77	      const id = armedZoneIdSignal(editor).get();
78	      if (!id) return undefined;
79	      const shape = editor.getShape(id);
80	      if (!shape || shape.type !== "mtg-zone") return undefined;
81	      return (shape.props as MtgZoneShapeProps).zone === "library" ? id : undefined;
82	    },
83	    [editor]
84	  );
85	}
