1	import { useEditor, useValue } from "tldraw";
2	import { useArmedLibraryZoneId } from "./zoneHitTest";
3	
4	/**
5	 * The library portal's arming visual (ticket 12) — a rotating pink/amber conic-gradient
6	 * swirl with a faint dark veil, rendered over the library while a card drags over it.
7	 * Local to the dragger (each browser computes its own armed state). Rendered via
8	 * `TLComponents.InFrontOfTheCanvas` (viewport space, in front of the canvas layer)
9	 * because the library's own opaque card-back picture sits on top of the zone shape
10	 * itself — a look this fleet's `--armed-glow` ring can't reach through, and a
11	 * deliberately distinct treatment from that ring (ticket 04's resolved design choice).
12	 */
13	export function LibraryPortalOverlay() {
14	  const editor = useEditor();
15	  const zoneId = useArmedLibraryZoneId(editor);
16	
17	  const rect = useValue(
18	    "libraryPortalViewportRect",
19	    () => {
20	      if (!zoneId) return undefined;
21	      const bounds = editor.getShapePageBounds(zoneId);
22	      if (!bounds) return undefined;
23	      const topLeft = editor.pageToViewport({ x: bounds.x, y: bounds.y });
24	      const zoom = editor.getZoomLevel();
25	      return { left: topLeft.x, top: topLeft.y, width: bounds.w * zoom, height: bounds.h * zoom };
26	    },
27	    [editor, zoneId]
28	  );
29	
30	  if (!rect) return null;
31	
32	  return (
33	    <div
34	      data-testid="portal-arming"
35	      style={{
36	        position: "absolute",
37	        left: rect.left,
38	        top: rect.top,
39	        width: rect.width,
40	        height: rect.height,
41	        overflow: "hidden",
42	        pointerEvents: "none",
43	      }}
44	    >
45	      <div
46	        style={{
47	          position: "absolute",
48	          inset: "-30%",
49	          background: "conic-gradient(from 0deg, var(--dark-pink), var(--armed-glow), var(--dark-pink))",
50	          animation: "library-portal-swirl-spin 1.6s linear infinite",
51	        }}
52	      />
53	      <div style={{ position: "absolute", inset: 0, background: "rgba(10, 6, 20, 0.4)" }} />
54	      <style>{`
55	        @keyframes library-portal-swirl-spin {
56	          from { transform: rotate(0deg); }
57	          to { transform: rotate(360deg); }
58	        }
59	      `}</style>
60	    </div>
61	  );
62	}
