1	import { Request, Response } from "express";
2	import { trace } from "@opentelemetry/api";
3	import { getOrCreateRoom } from "./rooms.js";
4	import { slugifyTableName, tableNameFromSlug } from "../shared/slugify.js";
5	import { sendCardReturnedToSpineBestEffort } from "./sendCardReturned.js";
6	
7	interface CardReturnedRequestBody {
8	  seatId?: string;
9	  scryfallId?: string;
10	  gameCardIndex?: number;
11	  fromZone?: string;
12	}
13	
14	/**
15	 * The library-portal swallow's send leg (ticket 12): the client has already decided to
16	 * swallow a card and needs a 2xx before it commits the shape's deletion (send-then-commit).
17	 * The client only knows the card's own props (`owner`, `scryfallId`, `gameCardIndex`) — it
18	 * has no notion of its own player identity, matching the rest of this ship's shared-canvas
19	 * design — so `seatId` here is the card's owner, and `playerName`/the Spine's real
20	 * `tableId` are resolved server-side from the room registry, the same lookup
21	 * `handleSeatJoined` already does.
22	 */
23	export async function handleCardReturned(req: Request, res: Response): Promise<void> {
24	  const tableName = slugifyTableName(req.params.tableName ?? "");
25	  if (!tableName) {
26	    res.status(400).json({ error: "table name required" });
27	    return;
28	  }
29	
30	  const body = req.body as CardReturnedRequestBody;
31	  const { seatId, scryfallId, gameCardIndex, fromZone } = body;
32	  if (!seatId || !scryfallId || typeof gameCardIndex !== "number") {
33	    res.status(400).json({ error: "seatId, scryfallId, and gameCardIndex are required" });
34	    return;
35	  }
36	
37	  const entry = getOrCreateRoom(tableName);
38	  if (!entry.spineTableId) {
39	    res.status(409).json({ error: "table has no live Spine subscription yet" });
40	    return;
41	  }
42	  const playerArea = entry.seats.get(seatId);
43	  if (!playerArea) {
44	    res.status(404).json({ error: "seat not found on this table" });
45	    return;
46	  }
47	
48	  trace.getActiveSpan()?.setAttributes({
49	    "table.name": tableNameFromSlug(tableName),
50	    "table.slug": tableName,
51	    "seat.id": seatId,
52	    "card.scryfall_id": scryfallId,
53	    "card.game_card_index": gameCardIndex,
54	  });
55	
56	  const ok = await sendCardReturnedToSpineBestEffort({
57	    tableId: entry.spineTableId,
58	    seatId,
59	    playerName: playerArea.playerName,
60	    scryfallId,
61	    gameCardIndex,
62	    ...(fromZone !== undefined ? { fromZone } : {}),
63	  });
64	
65	  if (ok) {
66	    res.status(200).json({ ok: true });
67	  } else {
68	    res.status(502).json({ ok: false, error: "the Spine did not confirm the card.returned event" });
69	  }
70	}
